import { drizzle } from "drizzle-orm/postgres-js"
import postgres from "postgres"

import { getServerEnv } from "@/env"

const globalForDb = globalThis as unknown as { __db?: ReturnType<typeof createDb> }

/**
 * `max` is per process: real usage is max x replicas, so size it against the server's
 * `max_connections`. Behind a transaction-mode pooler (PgBouncer, Supavisor) add `prepare: false`;
 * prepared statements do not survive pooled transactions.
 */
function createDb() {
  const { DATABASE_URL } = getServerEnv()
  const client = postgres(DATABASE_URL, { max: 8 })
  return drizzle(client, { casing: "snake_case" })
}

/** Cached on globalThis so Vite's dev HMR reuses one pool instead of leaking one per reload. */
export function getDb() {
  globalForDb.__db ??= createDb()
  return globalForDb.__db
}

export type Db = ReturnType<typeof getDb>

import { defineConfig } from "drizzle-kit"

export default defineConfig({
  out: "./drizzle",
  // One file per feature under schema/ (columns.ts, auth.ts, notes.ts, ...): items add files, never edit one.
  schema: "./src/lib/db/schema/*.ts",
  dialect: "postgresql",
  casing: "snake_case",
  dbCredentials: {
    url: process.env.DATABASE_URL!,
  },
})

/**
 * Apply the versioned SQL migrations in ./drizzle.
 * Prefer this over `drizzle-kit push` for anything shared or long-lived.
 */
import { drizzle } from "drizzle-orm/postgres-js"
import { migrate } from "drizzle-orm/postgres-js/migrator"
import postgres from "postgres"

const url = process.env.DATABASE_URL
if (!url) {
  console.error("DATABASE_URL missing: add it to .env first")
  process.exit(1)
}

console.log("migrate:", url.replace(/:[^:@/]+@/, ":***@"))

const client = postgres(url, { max: 1, connect_timeout: 20 })
const db = drizzle(client)

try {
  await migrate(db, { migrationsFolder: "./drizzle" })
  console.log("migrate ok")
} catch (error) {
  console.error("migrate failed:", error instanceof Error ? error.message : error)
  process.exit(1)
} finally {
  await client.end({ timeout: 5 })
}
